-- sql/2026-08-28_options_dd2024_sp-im5.sql
-- SP-IM5 — Options de Métamagie et de Manifestation occulte (DD2024).
--
-- Source : FR_SRD_CC_v5.2.1-classes.pdf, sections « Options de Métamagie »
--          et « Options de Manifestation occulte ».
--
-- ARBITRAGE du 2026-08-28 : ces options sont importées comme des DONS, dans
-- deux nouvelles catégories de dd_data_don, sur le modèle exact de la
-- catégorie 21 « Style de combat » déjà en service.
--   * même nature : une option nommée, choisie dans un pool, à un niveau donné ;
--   * do_conditions est le seul champ du schéma qui sache porter les prérequis
--     des manifestations (« Niveau d'Occultiste 9+, manifestation Pacte de la
--     lame ») ;
--   * on hérite de la liste compendium, de la fiche, du formulaire et du
--     sélecteur de dons sans créer de table.
--
-- PÉRIMÈTRE RÉDUIT par rapport au libellé initial de SP-IM5 :
--   * Styles de combat — DÉJÀ EN BASE : les 10 dons de catégorie 21, source 93.
--     Rien à importer.
--   * Bottes d'arme — HORS SUJET ICI : ce sont des propriétés d'ARME, décrites
--     dans FR_SRD_CC_v5.2.1.pdf (section équipement) et non dans le PDF des
--     classes. Elles relèvent de dd_equipements (table vide à ce jour) et d'un
--     lot d'import à part.
--
-- ⚠ do_resume n'est PAS du texte du SRD : ces résumés d'une ligne sont rédigés,
--   sur le modèle de ceux des 10 styles de combat. À relire.
--
-- ⚠ Le sélecteur de dons (detail-pp/dons-picker.php) ne filtre pas par classe :
--   ces options apparaîtront pour tout personnage, comme le font déjà les
--   styles de combat. Le filtrage par classe serait une phase SP-PE distincte.
--
-- IDEMPOTENCE : ids figés (catégories 22-23, dons 501+),
--   INSERT … ON DUPLICATE KEY UPDATE. Rejouable.

-- ------------------------------------------------------------
-- 1. Catégories de dons
-- ------------------------------------------------------------

INSERT INTO dd_data_don (dado_id, dado_nom, dado_abreviation, dado_ruleset_var_id)
VALUES
  (22, 'Métamagie',            'Méta', 2),
  (23, 'Manifestation occulte', 'MO',   2)
ON DUPLICATE KEY UPDATE
  dado_nom = VALUES(dado_nom), dado_abreviation = VALUES(dado_abreviation),
  dado_ruleset_var_id = VALUES(dado_ruleset_var_id);

-- ------------------------------------------------------------
-- 2. Les 10 options de Métamagie et les 28 manifestations occultes
-- ------------------------------------------------------------

INSERT INTO dd_dons
  (do_id, do_nom, do_dado_id, do_conditions, do_texte, do_resume,
   do_res_id, do_camp_id, do_public, do_visible, do_ruleset_var_id, do_page_source)
VALUES
  (501, 'Sort accéléré', 22, 'Aptitude Métamagie', '<p><b>Coût : 2 points de Sorcellerie</b></p><p>Lorsque vous lancez un sort dont le temps d’incantation est égal à 1 action, vous pouvez dépenser 2 points de Sorcellerie pour réduire son temps d’incantation à 1 action Bonus pour la présente incantation. Vous ne pouvez pas modifier un sort de cette manière si vous avez déjà lancé un sort du 1er niveau ou supérieur pendant le tour en cours, et pas davantage lancer un sort du 1er niveau ou supérieur pendant le tour en cours si vous avez déjà modifié un sort de cette manière.</p>', 'Réduit à une action Bonus le temps d’incantation d’un sort d’1 action.', 93, NULL, 0, 1, 2, 0),
  (502, 'Sort ample', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort dont la portée est supérieure ou égale à 1,50 m, vous pouvez dépenser 1 point de Sorcellerie pour doubler la portée de ce sort. Si vous lancez un sort dont la portée est « contact » et dépensez 1 point de Sorcellerie, sa portée devient 9 m.</p>', 'Double la portée du sort ; une portée « contact » passe à 9 m.', 93, NULL, 0, 1, 2, 0),
  (503, 'Sort chercheur', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Si vous effectuez un jet d’attaque pour un sort et échouez, vous pouvez dépenser 1 point de Sorcellerie pour relancer le d20, auquel cas c’est le nouveau jet qui s’applique.</p><p>Vous pouvez recourir à Sort chercheur même si vous avez déjà utilisé une autre option de Métamagie durant l’incantation du sort.</p>', 'Relance le d20 d’un jet d’attaque de sort raté.', 93, NULL, 0, 1, 2, 0),
  (504, 'Sort étendu', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort dont la durée est supérieure ou égale à 1 minute, vous pouvez dépenser 1 point de Sorcellerie pour doubler sa durée, jusqu’à un maximum de 24 heures.</p><p>Si le sort affecté nécessite la Concentration, vous avez l’Avantage à tous les jets de sauvegarde que vous effectuez pour maintenir cette Concentration.</p>', 'Double la durée du sort, jusqu’à 24 heures.', 93, NULL, 0, 1, 2, 0),
  (505, 'Sort intensifié', 22, 'Aptitude Métamagie', '<p><b>Coût : 2 points de Sorcellerie</b></p><p>Lorsque vous lancez un sort qui contraint une créature à effectuer un jet de sauvegarde, vous pouvez dépenser 2 points de Sorcellerie pour imposer le Désavantage à une cible du sort lors de ses JS contre ce sort.</p>', 'Impose le Désavantage aux JS d’une cible contre le sort.', 93, NULL, 0, 1, 2, 0),
  (506, 'Sort jumeau', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort, comme charme-personne, qui peut être lancé avec un emplacement de sort de plus haut niveau pour cibler une créature supplémentaire, vous pouvez dépenser 1 point de Sorcellerie pour augmenter de 1 le niveau effectif de ce sort.</p>', 'Augmente de 1 le niveau effectif d’un sort pour cibler une créature de plus.', 93, NULL, 0, 1, 2, 0),
  (507, 'Sort prévenant', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort qui contraint d’autres créatures à effectuer un jet de sauvegarde, vous pouvez protéger certaines de ces créatures des pleins effets du sort. À cette fin, dépensez 1 point de Sorcellerie et désignez des créatures dont le nombre n’excède pas votre modificateur de Charisme (minimum d’une créature). Les créatures choisies réussissent automatiquement leur jet de sauvegarde contre le sort et ne subissent aucun dégât si elles étaient censées les réduire de moitié en cas de réussite.</p>', 'Jusqu’à mod. de Charisme créatures réussissent d’office leur JS.', 93, NULL, 0, 1, 2, 0),
  (508, 'Sort renforcé', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Quand vous déterminez aléatoirement les dégâts d’un sort, vous pouvez dépenser 1 point de Sorcellerie afin de relancer un nombre de dés de dégâts égal à votre modificateur de Charisme (minimum d’un dé), auquel cas ce sont les nouveaux jets qui s’appliquent.</p><p>Vous pouvez recourir à Sort renforcé même si vous avez déjà utilisé une autre option de Métamagie durant l’incantation du sort.</p>', 'Relance jusqu’à mod. de Charisme dés de dégâts du sort.', 93, NULL, 0, 1, 2, 0),
  (509, 'Sort subtil', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort, vous pouvez dépenser 1 point de Sorcellerie pour le lancer sans ses composantes verbale, somatique ou matérielle, sauf en ce qui concerne les composantes matérielles que le sort consomme ou qui ont un coût exprimé dans le descriptif du sort.</p>', 'Lance le sort sans composante verbale, somatique ni matérielle.', 93, NULL, 0, 1, 2, 0),
  (510, 'Sort transmuté', 22, 'Aptitude Métamagie', '<p><b>Coût : 1 point de Sorcellerie</b></p><p>Lorsque vous lancez un sort qui inflige des dégâts d’un type de la liste suivante, vous pouvez dépenser 1 point de Sorcellerie pour changer ce type de dégâts en un autre de la liste : acide, feu, foudre, froid, poison, tonnerre.</p>', 'Change le type de dégâts du sort parmi six types élémentaires.', 93, NULL, 0, 1, 2, 0),
  (511, 'Armure d’ombres', 23, 'Aptitude Manifestations occultes', '<p>Vous pouvez lancer armure du mage sur vous-même sans dépenser d’emplacement de sort.</p>', 'Lance armure du mage sur soi sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (512, 'Buveuse de vie', 23, 'Niveau d’Occultiste 9+, manifestation Pacte de la lame', '<p>Une fois par tour, lorsque vous touchez une créature avec votre arme de pacte, vous pouvez lui infliger 1d6 points de dégâts supplémentaires nécrotiques, psychiques ou radiants (au choix), et vous pouvez dépenser l’un de vos dés de vie pour le lancer et regagner un nombre de points de vie égal au résultat obtenu + votre modificateur de Constitution (minimum de 1 point de vie).</p>', 'Une fois par tour, +1d6 dégâts avec l’arme de pacte et points de vie temporaires.', 93, NULL, 0, 1, 2, 0),
  (513, 'Décharge déchirante', 23, 'Niveau d’Occultiste 2+, un sort mineur d’Occultiste infligeant des dégâts', '<p>Choisissez l’un de vos sorts mineurs d’Occultiste connus qui inflige des dégâts. Vous pouvez ajouter votre modificateur de Charisme aux jets de dégâts de ce sort.</p><p><b>Répétable.</b> Vous pouvez recevoir cette manifestation plus d’une fois. Chaque fois, choisissez un sort mineur conforme différent.</p>', 'Ajoute le mod. de Charisme aux dégâts d’un sort mineur au choix. Répétable.', 93, NULL, 0, 1, 2, 0),
  (514, 'Décharge répulsive', 23, 'Niveau d’Occultiste 2+, un sort mineur d’Occultiste infligeant des dégâts via un jet d’attaque', '<p>Choisissez l’un de vos sorts mineurs d’Occultiste connus qui nécessite un jet d’attaque. Lorsque vous touchez une créature de taille G ou inférieure avec ce sort mineur, vous pouvez repousser cette créature de vous d’un maximum de 3 m, en ligne droite.</p><p><b>Répétable.</b> Vous pouvez recevoir cette manifestation plus d’une fois. Chaque fois, choisissez un sort mineur conforme différent.</p>', 'Repousse la cible touchée par un sort mineur au choix. Répétable.', 93, NULL, 0, 1, 2, 0),
  (515, 'Engagement du maître des chaînes', 23, 'Niveau d’Occultiste 5+, manifestation Pacte de la chaîne', '<p>Lorsque vous lancez appel de familier, vous insufflez une dose de puissance occulte au familier convoqué, ce qui lui octroie les bénéfices suivants.</p><p><b>Aérien ou aquatique.</b> Le familier reçoit une Vitesse de vol ou une Vitesse de nage (à votre convenance) de 12 m.</p><p><b>Attaque rapide.</b> Par une action Bonus, vous pouvez ordonner au familier d’entreprendre l’action Attaque.</p><p><b>Dégâts radiants ou nécrotiques.</b> Chaque fois que le familier inflige des dégâts contondants, perforants ou tranchants, vous pouvez décider qu’il inflige des dégâts radiants ou nécrotiques à la place.</p><p>Votre DD de sauvegarde. Si le familier impose un jet de sauvegarde à une créature, il le fait avec votre DD de sauvegarde des sorts.</p><p><b>Résistance.</b> Lorsque le familier subit des dégâts, vous pouvez jouer votre Réaction pour lui octroyer la Résistance contre ces dégâts.</p>', 'Octroie cinq bénéfices au familier d’appel de familier.', 93, NULL, 0, 1, 2, 0),
  (516, 'Enseignement des Premiers-Nés', 23, 'Niveau d’Occultiste 2+', '<p>Fort de la sapience d’une entité très ancienne du multivers, vous recevez le don d’origines de votre choix (cf. « Dons »).</p><p><b>Répétable.</b> Vous pouvez recevoir cette manifestation plus d’une fois. Chaque fois, choisissez un don d’origines différent.</p>', 'Octroie un don d’origines au choix. Répétable.', 93, NULL, 0, 1, 2, 0),
  (517, 'Esprit occulte', 23, 'Aptitude Manifestations occultes', '<p>Vous avez l’Avantage aux jets de sauvegarde de Constitution visant à maintenir la Concentration.</p>', 'Avantage aux JS de Constitution pour maintenir la Concentration.', 93, NULL, 0, 1, 2, 0),
  (518, 'Frappe occulte', 23, 'Niveau d’Occultiste 5+, manifestation Pacte de la lame', '<p>Une fois par tour lorsque vous touchez une créature avec votre arme de pacte, vous pouvez dépenser un emplacement de sort de Magie de pacte pour infliger 1d8 dégâts de force supplémentaires à la cible + 1d8 dégâts de force supplémentaires par niveau de l’emplacement de sort, et faire subir l’état À terre à la cible si celle-ci est de taille TG ou inférieure.</p>', 'Dépense un emplacement de Magie de pacte pour +1d8 dégâts de force par niveau.', 93, NULL, 0, 1, 2, 0),
  (519, 'Lame assoiffée', 23, 'Niveau d’Occultiste 5+, manifestation Pacte de la lame', '<p>Vous recevez l’aptitude Attaque supplémentaire avec votre arme de pacte uniquement. Cette aptitude vous permet d’attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaque à votre tour.</p>', 'Attaque supplémentaire, avec l’arme de pacte uniquement.', 93, NULL, 0, 1, 2, 0),
  (520, 'Lame dévorante', 23, 'Niveau d’Occultiste 12+, manifestation Lame assoiffée', '<p>L’attaque supplémentaire de votre manifestation Lame assoiffée octroie deux attaques supplémentaires au lieu d’une.</p>', 'Porte à deux les attaques supplémentaires de Lame assoiffée.', 93, NULL, 0, 1, 2, 0),
  (521, 'Lance occulte', 23, 'Niveau d’Occultiste 2+, un sort mineur d’Occultiste infligeant des dégâts', '<p>Choisissez l’un de vos sorts mineurs d’Occultiste connus qui inflige des dégâts et présente une portée de 3 m ou plus. Lorsque vous lancez ce sort, sa portée augmente de 9 m par niveau d’Occultiste.</p><p><b>Répétable.</b> Vous pouvez recevoir cette manifestation plus d’une fois. Chaque fois, choisissez un sort mineur conforme différent.</p>', 'Augmente la portée d’un sort mineur au choix. Répétable.', 93, NULL, 0, 1, 2, 0),
  (522, 'Maître des formes', 23, 'Niveau d’Occultiste 5+', '<p>Vous pouvez lancer modification d’apparence sans dépenser d’emplacement de sort.</p>', 'Lance modification d’apparence sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (523, 'Maître des ombres', 23, 'Niveau d’Occultiste 5+', '<p>Tant que vous vous trouvez dans une zone de Lumière faible ou de Ténèbres, vous pouvez lancer invisibilité sur vous-même sans dépenser d’emplacement de sort.</p>', 'Lance invisibilité sur soi sans emplacement, en Lumière faible ou Ténèbres.', 93, NULL, 0, 1, 2, 0),
  (524, 'Mille visages', 23, 'Niveau d’Occultiste 2+', '<p>Vous pouvez lancer déguisement sans dépenser d’emplacement de sort.</p>', 'Lance déguisement sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (525, 'Murmures de la tombe', 23, 'Niveau d’Occultiste 7+', '<p>Vous pouvez lancer communication avec les morts sans dépenser d’emplacement de sort.</p>', 'Lance communication avec les morts sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (526, 'Pacte de la chaîne', 23, 'Aptitude Manifestations occultes', '<p>Vous apprenez le sort appel de familier que vous pouvez lancer au prix de l’action Magie sans dépenser d’emplacement de sort.</p><p>À l’incantation du sort, vous pouvez choisir l’une des formes normales pour votre familier ou l’une des formes spéciales suivantes : Diablotin, esprit follet, pseudodragon, quasit, sphinx merveilleux, serpent venimeux ou squelette (cf. « Monstres » pour le profil du familier).</p><p>En outre, lorsque vous entreprenez l’action Attaque, vous pouvez renoncer à l’une de vos attaques pour permettre à votre familier d’effectuer l’une de ses attaques en jouant sa Réaction.</p>', 'Apprend appel de familier, avec des formes et une attaque supplémentaires.', 93, NULL, 0, 1, 2, 0),
  (527, 'Pacte de la lame', 23, 'Aptitude Manifestations occultes', '<p>Par une action Bonus, vous pouvez invoquer une arme de pacte dans votre main (arme de corps à corps courante ou de guerre de votre choix) avec laquelle vous créez un lien, ou créer un lien avec une arme magique que vous touchez ; créer un tel lien est impossible avec une arme magique si une autre créature est harmonisée avec celle-ci, ou si un autre Occultiste a déjà créé un lien avec cette arme. Jusqu’à ce que le lien prenne fin, vous avez la maîtrise de l’arme et pouvez l’utiliser comme focaliseur d’incantation.</p><p>Chaque fois que vous attaquez avec l’arme à laquelle vous êtes lié, vous pouvez utiliser votre modificateur de Charisme pour les jets d’attaque et de dégâts à la place du modificateur de Force ou de Dextérité ; vous pouvez en outre utiliser l’arme pour infliger des dégâts nécrotiques, psychiques ou radiants au lieu de son type de dégâts normal.</p><p>Votre lien avec l’arme prend fin si vous recourez de nouveau à l’action Bonus de cette aptitude, si l’arme se retrouve à plus de 1,50 m de vous pendant 1 minute ou plus, ou si vous mourez. Une arme invoquée disparaît lorsque le lien prend fin.</p>', 'Invoque une arme de pacte liée, au Charisme et aux dégâts magiques.', 93, NULL, 0, 1, 2, 0),
  (528, 'Pacte du grimoire', 23, 'Aptitude Manifestations occultes', '<p>En cousant ensemble des filaments d’ombre, vous invoquez un grimoire qui apparaît dans votre main à la fin d’un Repos court ou long. Ce Codex des Ombres (il vous appartient d’en déterminer l’apparence) renferme une magie occulte à laquelle vous seul avez accès, et qui vous octroie les bénéfices suivants. Le grimoire disparaît si vous en invoquez un autre par le biais de cette aptitude ou si vous mourez.</p><p><b>Sorts mineurs et rituels.</b> Lorsque le grimoire apparaît, choisissez trois sorts mineurs, puis deux sorts du 1er niveau portant la mention « rituel ». Ces sorts peuvent appartenir à la liste de sorts de n’importe quelle classe, et doivent être des sorts que vous n’avez pas déjà préparés. Tant que le grimoire est sur vous, les sorts choisis sont préparés et fonctionnent pour vous comme des sorts d’Occultiste.</p><p><b>Focaliseur d’incantation.</b> Vous pouvez vous servir du grimoire comme focaliseur d’incantation.</p>', 'Invoque le Codex des Ombres : 3 sorts mineurs et 2 rituels, focaliseur.', 93, NULL, 0, 1, 2, 0),
  (529, 'Pas aérien', 23, 'Niveau d’Occultiste 5+', '<p>Vous pouvez lancer lévitation sur vous-même sans dépenser d’emplacement de sort.</p>', 'Lance lévitation sur soi sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (530, 'Perception transférée', 23, 'Niveau d’Occultiste 5+', '<p>Par une action Bonus, vous pouvez toucher une créature consentante afin de percevoir à travers ses sens jusqu’à la fin de votre tour suivant. Lors des tours suivants et tant que cette créature se trouve sur le même plan d’existence que vous, vous pouvez maintenir cette connexion sensorielle par une action Bonus, ce qui prolonge la durée de l’effet jusqu’à la fin de votre tour suivant. La connexion prend fin si vous cessez de la maintenir par ce biais.</p><p>Tant que vous percevez le monde par les sens de l’autre créature, vous bénéficiez de tous les sens spéciaux dont elle dispose, et vous pouvez lancer des sorts comme si vous étiez dans votre espace ou dans l’espace de l’autre créature à condition que 18 m ou moins vous séparent.</p>', 'Perçoit à travers les sens d’une créature consentante touchée.', 93, NULL, 0, 1, 2, 0),
  (531, 'Présent des profondeurs', 23, 'Niveau d’Occultiste 5+', '<p>Vous recevez une Vitesse de nage égale à votre Vitesse et pouvez respirer sous l’eau.</p><p>Vous pouvez en outre lancer respiration aquatique une fois sans dépenser d’emplacement de sort. Vous devez terminer un Repos long avant de pouvoir le relancer ainsi.</p>', 'Vitesse de nage égale à la Vitesse, respiration aquatique.', 93, NULL, 0, 1, 2, 0),
  (532, 'Présent des sauveurs', 23, 'Niveau d’Occultiste 9+, manifestation Pacte du grimoire', '<p>Une nouvelle page apparaît dans votre Codex des Ombres quand vous l’invoquez. Avec votre permission, une créature peut entreprendre une action afin d’écrire son nom sur cette page, qui peut contenir autant de noms que votre modificateur de Charisme (un nom au minimum).</p><p>Quand une créature dont le nom figure sur la page tombe à 0 point de vie sans être tuée sur le coup, elle tombe en fait magiquement à 1 point de vie. Une fois cette magie activée, aucune créature ne peut plus en profiter jusqu’à ce que vous terminiez un Repos long.</p><p>Au prix de l’action Magie, vous pouvez effacer un nom figurant sur la page, d’un simple contact.</p>', 'Les noms inscrits au Codex des Ombres reçoivent un secours à 0 pv.', 93, NULL, 0, 1, 2, 0),
  (533, 'Royaumes lointains', 23, 'Niveau d’Occultiste 9+', '<p>Vous pouvez lancer œil du mage sans dépenser d’emplacement de sort.</p>', 'Lance œil du mage sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (534, 'Saut d’outre-monde', 23, 'Niveau d’Occultiste 2+', '<p>Vous pouvez lancer saut sur vous-même sans dépenser d’emplacement de sort.</p>', 'Lance saut sur soi sans emplacement de sort.', 93, NULL, 0, 1, 2, 0),
  (535, 'Vigueur fiélonne', 23, 'Niveau d’Occultiste 2+', '<p>Vous pouvez lancer simulacre de vie sur vous-même sans dépenser d’emplacement de sort. À l’incantation du sort avec cette aptitude, vous ne lancez pas le dé pour les points de vie temporaires ; vous obtenez automatiquement le résultat le plus élevé du dé.</p>', 'Lance simulacre de vie sur soi sans emplacement, points de vie maximisés.', 93, NULL, 0, 1, 2, 0),
  (536, 'Vision du diable', 23, 'Niveau d’Occultiste 2+', '<p>Vous voyez normalement en conditions de Lumière faible et de Ténèbres, que celles-ci soient magiques ou non, dans un rayon de 36 m.</p>', 'Voit normalement en Lumière faible et Ténèbres sur 36 m.', 93, NULL, 0, 1, 2, 0),
  (537, 'Vision sorcière', 23, 'Niveau d’Occultiste 15+', '<p>Vous disposez de la Vision lucide sur 9 m.</p>', 'Vision lucide sur 9 m.', 93, NULL, 0, 1, 2, 0),
  (538, 'Visions embrumées', 23, 'Niveau d’Occultiste 2+', '<p>Vous pouvez lancer image silencieuse sans dépenser d’emplacement de sort.</p>', 'Lance image silencieuse sans emplacement de sort.', 93, NULL, 0, 1, 2, 0)
ON DUPLICATE KEY UPDATE
  do_nom = VALUES(do_nom), do_dado_id = VALUES(do_dado_id),
  do_conditions = VALUES(do_conditions), do_texte = VALUES(do_texte),
  do_resume = VALUES(do_resume), do_res_id = VALUES(do_res_id),
  do_ruleset_var_id = VALUES(do_ruleset_var_id);
